public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (java.util.Arrays.equals(start, end)) return "can be travelled";
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length != 2 * n) continue;
        String keyA = java.util.Arrays.toString(java.util.Arrays.copyOfRange(path, 0, n));
        String keyB = java.util.Arrays.toString(java.util.Arrays.copyOfRange(path, n, 2 * n));
        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);
    if (!adj.containsKey(startKey) || !adj.containsKey(endKey)) {
        return "cannot be travelled";
    }
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) return "can be travelled";
        for (String nb : adj.getOrDefault(cur, java.util.Collections.emptyList())) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

