public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    long totalSum = 0;
    for (int num : nums) totalSum += num;

    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);

    for (int num : nums) {
        for (int i = n - 1; i >= 1; i--) {
            for (int sum : dp[i - 1]) {
                dp[i].add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (int) ((totalSum * k) / n);
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

