public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0; // number of unmatched '('

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--; // match with a previous '('
            } else {
                // need an extra '(' before this ')'
                insertions++;
            }
        }
    }

    // any remaining unmatched '(' need a ')' each
    insertions += balance;
    return insertions;
}

