public String getSmallestString(int n, int k) {
    // Initialize all characters to 'a' (value 1)
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // Remaining value to distribute
    int remaining = k - n; // since each 'a' contributes 1

    // Distribute the remaining value from the end to make the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to a position (from 'a' to 'z')
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

