public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] dpH = new int[m][n]; // horizontal
    int[][] dpV = new int[m][n]; // vertical
    int[][] dpD = new int[m][n]; // diagonal (top-left to bottom-right)
    int[][] dpAD = new int[m][n]; // anti-diagonal (top-right to bottom-left)
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;
                int currentMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                          Math.max(dpD[i][j], dpAD[i][j]));
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpAD[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long num = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        count++;
        if (num > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && h < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int k = 0; k <= m + n - 2; k++) {
        if (k % 2 == 0) {
            int i = Math.min(k, m - 1);
            int j = k - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(k, n - 1);
            int i = k - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    // Find the first index from the right where digits[i] < digits[i+1]
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No higher permutation exists
        return -1;
    }
    // Find the smallest digit on the right side of i that is greater than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the suffix starting at i+1
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to integer
    return Integer.parseInt(new String(digits));
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    // Check for duplicate points
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }
    // Compute cross product to check collinearity
    int cross = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0]);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
